from lib import *
recs=[
R(8866678,"Moussaka de légumes du Hedjaz",
"La moussaka telle qu'on la prépare dans les foyers du Hedjaz : aubergine, pomme de terre et carotte avec oignon et piment dans une sauce tomate épaisse, servie avec du riz ou du pain. Ici, les légumes sont rôtis au four avec un peu d'huile d'olive au lieu d'être frits, et le concentré de tomate est sans sel ajouté.",
"4","1 assiette (environ 330 g)",
["2 aubergines moyennes, coupées en dés (500 g)","2 pommes de terre moyennes, pelées et coupées en dés (250 g)","2 carottes, coupées en petits dés (150 g)","1 1/2 cuillère à soupe d'huile d'olive (22,5 g)","1 gros oignon, émincé (150 g)","2 piments verts, finement émincés (15 g)","3 gousses d'ail, écrasées (10 g)","3 tomates, hachées (300 g)","1 cuillère à soupe de concentré de tomate sans sel ajouté (15 g)","1/2 cuillère à café de poivre noir, 1/2 cuillère à café de cumin et 1/2 cuillère à café de coriandre moulue","1 grosse pincée de sel (2,5 g)"],
["Faites tremper les dés de pomme de terre dans de l'eau tiède 30 minutes, puis égouttez et séchez.","Chauffez le four à 220 °C. Mélangez l'aubergine, la pomme de terre et la carotte avec 1 cuillère à soupe d'huile et étalez-les sur une plaque garnie de papier sulfurisé.","Faites rôtir 25–30 minutes en retournant une fois, jusqu'à ce qu'ils soient dorés et tendres.","Dans une marmite, chauffez le reste de l'huile et faites ramollir l'oignon et le piment sans les dorer, puis ajoutez l'ail.","Ajoutez la tomate, le concentré de tomate, les épices, le sel et 100 ml d'eau et faites cuire 10 minutes jusqu'à ce que ce soit épais.","Ajoutez les légumes rôtis, remuez délicatement, couvrez et laissez mijoter 10 minutes pour qu'ils absorbent la sauce. Servez chaud ou tiède."],
["Ce qui a changé : les légumes sont rôtis avec une cuillère d'huile au lieu d'être frits, avec du concentré de tomate sans sel et peu de sel.","Conseil pour les reins : la pomme de terre, la tomate et l'aubergine contiennent du potassium ; coupez les pommes de terre en petits morceaux et faites-les bouillir dans beaucoup d'eau 10 minutes, en jetant l'eau, avant de les rôtir, ou remplacez-les par plus d'aubergine et de carotte, et limitez-vous à une petite assiette.","Conseil pour le diabète : une assiette contient environ 30 g de glucides provenant des pommes de terre ; si vous servez avec du riz ou du pain, réduisez le riz ou le pain de moitié.","Convient à : personnes diabétiques, santé cardiaque et tension artérielle, végétariens, régime sans gluten.","Références : Encyclopedia Cooking, Sayidaty Kitchen, Mawdoo3"]),
R(8872488,"Mantu du Hedjaz",
"Les mantu sont des raviolis farcis de viande hachée et d'oignon et cuits à la vapeur ; c'est un plat bien connu d'origine boukhare au Hedjaz, surtout à La Mecque et à Djeddah, servi avec une sauce au yaourt et une sauce tomate pimentée. Cette version utilise moitié farine complète, de la viande maigre, du yaourt allégé et peu de sel, et les mantu sont cuits à la vapeur, pas frits.",
"4","6 raviolis avec les deux sauces (environ 350 g)",
[["Pour la pâte","100 g de farine complète"],["Pour la pâte","100 g de farine blanche"],["Pour la pâte","1 œuf (50 g)"],["Pour la pâte","1 pincée de sel (1 g)"],["Pour la pâte","environ 90 ml d'eau"],["Pour la farce","500 g de bœuf haché maigre (90 % de maigre)"],["Pour la farce","2 oignons moyens (200 g), râpés et pressés"],["Pour la farce","1 cuillère à café de cumin, 1/2 cuillère à café de poivre noir, 1/4 cuillère à café de piment en poudre"],["Pour la farce","⅓ cuillère à café de sel (2 g)"],["Pour la farce","1 cuillère à café d'huile d'olive pour graisser le cuit-vapeur (4,5 g)"],["Pour la sauce au yaourt","200 g de yaourt allégé"],["Pour la sauce au yaourt","1 gousse d'ail (4 g), écrasée, et 1/2 cuillère à café de menthe séchée"],["Pour la sauce pimentée","2 tomates (200 g)"],["Pour la sauce pimentée","1 piment vert (10 g) et 1 gousse d'ail (4 g)"],["Pour la sauce pimentée","1 cuillère à soupe de jus de citron (15 ml) et 1 poignée de coriandre fraîche (10 g)"]],
["Mélangez les deux farines avec le sel et l'œuf, ajoutez l'eau petit à petit et pétrissez jusqu'à obtenir une pâte souple et lisse qui ne colle pas. Couvrez et laissez reposer 30 minutes.","Mélangez bien la viande avec l'oignon pressé, le cumin, le poivre noir, le piment et le sel.","Étalez finement la pâte et découpez-la en 24 carrés (d'environ 8 cm). Mettez une cuillère de farce au milieu de chacun, rabattez les quatre coins par-dessus et pincez bien pour fermer.","Graissez les paniers du cuit-vapeur avec l'huile, disposez les mantu en les espaçant, posez-les au-dessus d'eau bouillante, couvrez et faites cuire à la vapeur 35–40 minutes jusqu'à ce que la farce soit cuite.","Pour la sauce au yaourt : mélangez le yaourt avec l'ail et la menthe.","Pour la sauce pimentée : mixez par impulsions les tomates, le piment, l'ail, le jus de citron et la coriandre jusqu'à obtenir une texture grossière.","Servez les mantu chauds avec les deux sauces et une légère pincée de cumin et de poivre noir."],
["Ce qui a changé : les mantu sont cuits à la vapeur, pas frits, la moitié de la farine est complète, de la viande à 90 % de maigre remplace la viande grasse et le ghee, le yaourt est allégé, et la sauce pimentée est faite de tomate fraîche sans sel ajouté.","Conseil pour les reins : la viande, le yaourt et la tomate apportent du phosphore et du potassium ; mangez 4 raviolis au lieu de 6, prenez seulement 2 cuillères à soupe de sauce au yaourt, et remplacez la tomate de la sauce pimentée par du poivron rouge rôti.","Conseil pour le diabète : une portion (6 raviolis) contient environ 48 g de glucides ; servez avec une grande salade verte et sans riz ni pain en plus.","Convient à : personnes diabétiques.","Références : Encyclopedia Cooking, Layalina Yummy, Mawdoo3"]),
R(8874214,"Fatit du Qassim",
"Le fatit est un biscuit traditionnel du Najd, célèbre à Al-Qassim : des biscuits ronds friables de farine complète à la cardamome, au gingembre et au safran, cuits au four et servis avec un sirop de miel, cannelle et citron vert noir. Cette version utilise moins d'un tiers du sucre habituel, moins de la moitié de l'huile et du lait écrémé en poudre.",
"16","1 galette (environ 35 g) avec 1 cuillère à café de sirop",
[["Pour la pâte","300 g de farine complète"],["Pour la pâte","2 cuillères à soupe de lait écrémé en poudre (15 g)"],["Pour la pâte","1 œuf (50 g)"],["Pour la pâte","1 cuillère à café de levure chimique (4 g)"],["Pour la pâte","60 g de sucre (5 cuillères à soupe)"],["Pour la pâte","60 ml d'huile d'olive douce (55 g)"],["Pour la pâte","1 pincée de sel (1 g)"],["Pour la pâte","1/2 cuillère à café de cardamome moulue"],["Pour la pâte","1/2 cuillère à café de gingembre moulu"],["Pour la pâte","1 pincée de safran trempée dans 1 cuillère à soupe d'eau (ou 1/4 cuillère à café de curcuma)"],["Pour la pâte","environ 150 ml d'eau"],["Pour le sirop","2 cuillères à soupe de miel (40 g)"],["Pour le sirop","60 ml d'eau"],["Pour le sirop","1 cuillère à café de cannelle moulue"],["Pour le sirop","1/2 cuillère à café de cardamome moulue"],["Pour le sirop","1/2 cuillère à café de citron vert noir (loomi) moulu"]],
["Chauffez le four à 190 °C en chaleur haute et basse et garnissez deux plaques de papier sulfurisé.","Fouettez l'œuf avec le sucre, l'huile, le safran trempé, la cardamome, le gingembre et le sel.","Mélangez la farine avec le lait en poudre et la levure chimique, ajoutez-la au mélange d'œuf avec l'eau petit à petit, et pétrissez jusqu'à obtenir une pâte ferme facile à façonner et qui ne colle pas.","Divisez la pâte en 16 boules et aplatissez chacune en une galette d'environ 1 cm d'épaisseur. Pressez-la avec un moule à fatit en bois, ou avec un panier ou une passoire, pour former le motif.","Faites cuire 15–20 minutes jusqu'à ce que les bords et le dessous soient dorés, puis laissez refroidir sur une grille.","Pour le sirop : faites mijoter l'eau avec le miel, la cannelle, la cardamome et le citron vert noir 2 minutes jusqu'à ce que ça épaississe légèrement, puis filtrez.","Servez chaque galette avec 1 cuillère à café de sirop versé dessus ou à côté pour tremper."],
["Ce qui a changé : 60 g de sucre au lieu d'environ 200 g, 60 ml d'huile au lieu d'environ 180 ml, lait écrémé en poudre, et un sirop de miel plus léger en petite quantité par galette.","Conseil pour les reins : la farine complète, le lait en poudre et la levure chimique contiennent du phosphore ; limitez-vous à une galette, et vous pouvez utiliser de la levure chimique pauvre en sodium et moitié farine blanche.","Conseil pour le diabète : une galette contient environ 20 g de glucides dont 6 g de sucre ajouté ; prenez-en une avec du café arabe non sucré et supprimez le sirop si possible.","Convient à : personnes diabétiques, santé cardiaque et tension artérielle, maladie rénale (sans dialyse), personnes sous dialyse, végétariens.","Références : Encyclopedia Cooking, Wikipédia en arabe (Fatit), Khaleej Kitchen (kleicha du Qassim)"]),
R(8879817,"Hareis rouge du Najd",
"Le hareis du Najd est du blé complet mijoté pendant des heures avec de la viande, de la tomate et des épices, puis battu jusqu'à obtenir une texture lisse et garni d'une kishna d'oignon ; il est populaire au Najd et à Hail lors des grandes occasions. Cette version utilise de la viande maigre, une cuillère d'huile et un peu de ghee dans la kishna au lieu de beaucoup de ghee, du concentré de tomate sans sel ajouté et peu de sel.",
"4","1 bol (environ 400 g)",
[["Pour le hareis","240 g de blé hareis (blé complet décortiqué), lavé et trempé 2 heures"],["Pour le hareis","600 g de veau ou de chameau jeune maigre désossé, gras visible retiré, coupé en dés"],["Pour le hareis","1 cuillère à soupe d'huile d'olive (13,5 g)"],["Pour le hareis","1 gros oignon, finement haché (150 g)"],["Pour le hareis","2 grosses tomates, râpées (250 g)"],["Pour le hareis","2 cuillères à soupe de concentré de tomate sans sel ajouté (30 g)"],["Pour le hareis","1 cuillère à café d'épices saoudiennes mélangées (bezar), 1 cuillère à café de curcuma, 1/2 cuillère à café de piment rouge moulu, 1/2 cuillère à café de cardamome"],["Pour le hareis","Environ 2,5 l d'eau bouillante"],["Pour le hareis","3/4 cuillère à café de sel (4,5 g)"],["Pour la garniture kishna","2 cuillères à café de ghee (9 g)"],["Pour la garniture kishna","1 oignon moyen, finement émincé (100 g)"],["Pour la garniture kishna","1 piment vert, haché (15 g)"],["Pour la garniture kishna","1/2 cuillère à café de citron vert séché (loomi) moulu"]],
["Chauffez l'huile dans une grande marmite épaisse et faites cuire l'oignon jusqu'à ce qu'il soit tendre, puis ajoutez la viande et les épices et faites dorer 8–10 minutes.","Ajoutez la tomate râpée et le concentré de tomate et remuez 5 minutes jusqu'à ce que ce soit épais.","Ajoutez le blé égoutté et l'eau bouillante, portez à ébullition, puis baissez le feu au minimum, couvrez et faites cuire 3 1/2–4 heures, en remuant de temps en temps et en ajoutant de l'eau bouillante si nécessaire (ou 1 1/2 heure à l'autocuiseur).","Ajoutez le sel pendant la dernière heure, puis battez le hareis tant qu'il est chaud avec un pilon en bois ou un mixeur plongeant jusqu'à ce que la viande se défasse et se mélange au blé.","Pour la kishna : chauffez le ghee dans une petite poêle et faites dorer l'oignon, puis ajoutez le piment et le citron vert séché 1 minute.","Étalez le hareis dans un plat de service, nappez de kishna et servez chaud avec une salade verte."],
["Ce qui a changé : viande maigre, 1 cuillère à soupe d'huile et 2 cuillères à café de ghee pour toute la marmite au lieu de beaucoup de beurre et de ghee, concentré de tomate sans sel ajouté au lieu d'une boîte entière de sauce tomate, et moins de sel.","Conseil pour les reins : le blé complet et la viande sont riches en phosphore, et la tomate et le concentré de tomate en potassium ; utilisez moitié moins de concentré de tomate, limitez-vous à une portion (environ 100 g de viande cuite) et demandez à votre diététicien ce qu'il en est des céréales complètes.","Conseil pour le diabète : un bol contient environ 53 g de glucides issus de céréales complètes riches en fibres ; mangez-le avec une salade et n'ajoutez pas de sucre dessus.","Convient à : personnes diabétiques, santé cardiaque et tension artérielle.","Références : Encyclopedia Cooking (encyclopediacooking.com), Sayidaty Kitchen (hareis à la viande et à l'oignon), Saudipedia (plats populaires de Hail)"]),
R(8882310,"Riz Boukhari au poulet",
"Le riz Boukhari est un plat bien connu du Hedjaz, à La Mecque, à Médine et à Djeddah, aux racines boukhares : du riz basmati cuit dans un bouillon de poulet épicé avec des carottes, garni de carottes et de raisins secs et servi avec du poulet doré au four. Cette version utilise du poulet sans peau, un peu d'huile d'olive et du concentré de tomate non salé, sans cubes de bouillon ni sauce soja.",
"4","1 assiette (environ 420 g)",
[["Pour le poulet","300 g de blanc de poulet sans peau, en 2 morceaux"],["Pour le poulet","300 g de cuisses de poulet désossées sans peau"],["Pour le poulet","1 oignon moyen (150 g), finement haché"],["Pour le poulet","3 gousses d'ail (10 g), écrasées"],["Pour le poulet","2 tomates (200 g), hachées"],["Pour le poulet","1 cuillère à soupe de concentré de tomate sans sel ajouté (15 g)"],["Pour le poulet","zeste de 1/2 orange (5 g)"],["Pour le poulet","épices entières : 5 gousses de cardamome, 4 clous de girofle, 1 bâton de cannelle, 1 feuille de laurier, 1/2 cuillère à café de grains de poivre noir"],["Pour le poulet","épices Boukhari moulues : 1 cuillère à café de cumin, 1/2 cuillère à café de coriandre, 1/2 cuillère à café de citron noir, 1/4 cuillère à café de cardamome"],["Pour le poulet","1/4 cuillère à café de curcuma pour dorer"],["Pour le riz","200 g de riz basmati, lavé et trempé 30 minutes"],["Pour le riz","3/4 cuillère à café de sel (5 g)"],["Pour le riz et la garniture","2 grosses carottes (250 g), coupées en fins bâtonnets"],["Pour le riz et la garniture","30 g de raisins secs"],["Pour le riz et la garniture","2 cuillères à soupe d'huile d'olive (27 g)"]],
["Chauffez 1 cuillère à soupe d'huile dans une marmite et faites cuire l'oignon avec les épices entières jusqu'à ce qu'il soit tendre et légèrement doré, puis ajoutez l'ail et le zeste d'orange et remuez.","Ajoutez le poulet et retournez-le jusqu'à ce qu'il change de couleur, puis ajoutez la tomate, le concentré de tomate et un quart des carottes et remuez 2 minutes.","Ajoutez 800 ml d'eau chaude, portez à ébullition, puis laissez mijoter 25–30 minutes, en ajoutant les épices moulues pendant les 5 dernières minutes.","Déposez le poulet sur une plaque de four, filtrez le bouillon et mesurez-en 400 ml.","Remettez le bouillon dans la marmite avec le sel ; quand il bout, ajoutez le riz égoutté et la moitié des carottes restantes. Faites cuire à feu vif jusqu'à ce que le liquide soit absorbé, puis couvrez hermétiquement et laissez à feu très doux 20 minutes.","Pendant ce temps, mélangez 3 cuillères à soupe de bouillon avec le curcuma et 1 cuillère à café d'huile, badigeonnez-en le poulet et faites-le griller à 220 °C (chaleur du haut) 10–15 minutes en le badigeonnant une ou deux fois, jusqu'à ce qu'il soit doré.","Chauffez le reste de l'huile dans une poêle et remuez les carottes restantes jusqu'à ce qu'elles soient tendres, puis ajoutez les raisins secs une minute.","Déposez le riz sur un plat, parsemez les carottes et les raisins secs sur le bord, posez le poulet au milieu et servez avec une salade de tomate et de concombre."],
["Ce qui a changé : poulet sans peau au lieu d'un poulet entier avec la peau, seulement 2 cuillères à soupe d'huile, concentré de tomate sans sel ajouté, pas d'assaisonnement en poudre, de sauce soja ni de sucre sur les carottes, et zeste d'orange et citron noir pour la saveur au lieu de sel supplémentaire.","Conseil pour les reins : la tomate, le concentré de tomate, les raisins secs et les carottes apportent du potassium ; utilisez une tomate, réduisez les raisins secs à 15 g et limitez-vous à environ 90 g de poulet cuit par portion.","Conseil pour le diabète : une portion contient environ 59 g de glucides ; limitez-vous à 150 g de riz cuit, vous pouvez en faire moitié riz complet, et servez avec une grande salade.","Convient à : personnes diabétiques, régime sans gluten.","Références : Encyclopedia Cooking, magazine Hia, Sayidaty Kitchen"]),
R(8888089,"Mahmous de Qatif au poulet",
"Le mahmous est un plat de riz de Qatif, d'Al-Ahsa et de Bahreïn, brun foncé grâce à une grande quantité d'oignon rôti jusqu'à être presque noir et au citron vert noir séché, cuit avec du poulet, de la viande ou du poisson. Ici, les oignons sont caramélisés lentement avec des filets d'eau et beaucoup moins d'huile, avec du poulet sans peau, peu de sel et sans cubes de bouillon.",
"4","1 assiette (environ 420 g)",
["600 g de poulet sans peau (cuisses et blancs), coupé en 8 morceaux","200 g de riz basmati, lavé et trempé 30 minutes (environ 250 ml)","5 oignons moyens, finement émincés (500 g)","2 cuillères à soupe d'huile d'olive (28 g)","5 gousses d'ail, écrasées (15 g)","3 citrons verts noirs séchés (loomi) percés","Épices entières : 1 bâton de cannelle, 5 gousses de cardamome, 4 clous de girofle, 2 feuilles de laurier","2 cuillères à café d'épices mélangées sans sel (bezar), 3/4 cuillère à café de curcuma, 1/2 cuillère à café de poivre noir","3/4 cuillère à café de sel (4,5 g)","environ 900 ml d'eau chaude"],
["Mettez les oignons dans une large marmite épaisse à feu moyen avec un filet d'eau et remuez jusqu'à ce qu'ils soient tendres et que l'eau se soit évaporée.","Ajoutez l'huile et continuez à remuer 25–30 minutes, en ajoutant un filet d'eau dès que ça commence à attacher, jusqu'à ce que les oignons soient brun très foncé mais pas brûlés.","Ajoutez les épices entières et moulues et l'ail et remuez 2 minutes, puis ajoutez un filet d'eau et couvrez 3 minutes.","Ajoutez le poulet et retournez-le 10 minutes jusqu'à ce qu'il soit enrobé du brun des oignons.","Ajoutez l'eau chaude, le loomi et le sel, couvrez et laissez mijoter 30 minutes jusqu'à ce que le poulet soit cuit.","Déposez le poulet sur une plaque et faites-le dorer dans un four préchauffé à 220 °C pendant 10 minutes sans matière grasse ajoutée.","Mesurez le bouillon : il en faut environ 375 ml. Ajoutez le riz égoutté et faites bouillir à découvert sans remuer jusqu'à ce que le bouillon soit absorbé.","Mettez le feu au minimum, couvrez et faites cuire 20 minutes jusqu'à ce que le riz soit cuit.","Déposez le riz sur un plat, garnissez de poulet et servez avec une salade verte et du concombre."],
["Ce qui a changé : les oignons sont rôtis dans 2 cuillères à soupe d'huile avec des filets d'eau au lieu d'être couverts d'huile, le poulet est sans peau et doré au four, il n'y a pas de cubes de bouillon, et la portion de riz est d'environ 150 g cuit par personne.","Conseil pour les reins : le poulet est riche en phosphore et en potassium ; limitez-vous à une assiette (environ 100 g de poulet cuit). Le plat ne contient ni tomate ni pomme de terre, il est donc plus pauvre en potassium que beaucoup de plats de riz.","Conseil pour le diabète : une assiette contient environ 54 g de glucides ; servez avec une grande salade, et vous pouvez mélanger un quart de riz complet.","Convient à : personnes diabétiques, régime sans gluten.","Références : Encyclopedia Cooking (Mawsouat Al Tabkh), Wikipédia, Cookinsta"]),
R(8892072,"Shakshouka",
"La shakshouka saoudienne est un petit-déjeuner familial courant : oignon, ail, tomate et piment vert sont cuits avec du cumin en une sauce épaisse, puis des œufs y sont incorporés jusqu'à ce qu'ils prennent, et on la mange avec du pain. Cette version utilise un peu d'huile d'olive, moins de sel, des blancs d'œufs à la place d'une partie des œufs entiers et plus de légumes.",
"4","1 assiette (environ 250 g), sans pain",
["4 œufs entiers (200 g) et 2 blancs d'œufs (66 g)","2 oignons moyens, hachés (220 g)","3 gousses d'ail, hachées (10 g)","3 tomates moyennes, hachées (360 g)","1 cuillère à soupe de concentré de tomate sans sel ajouté (15 g)","2 piments verts (20 g) et 1 petit poivron vert (100 g), hachés","1 cuillère à soupe d'huile d'olive (13,5 g)","1/2 cuillère à café de cumin, 1/2 cuillère à café de bezar, une pincée de poivre noir","1 grosse pincée de sel (2,5 g)","10 g de coriandre fraîche, hachée"],
["Chauffez l'huile d'olive dans une large poêle et faites cuire l'oignon jusqu'à ce qu'il soit tendre, puis ajoutez l'ail, les piments et le poivron et remuez 2 minutes.","Incorporez le cumin et le bezar, puis ajoutez les tomates, le concentré de tomate et 50 ml d'eau et couvrez 8–10 minutes jusqu'à ce que la sauce soit épaisse.","Fouettez les œufs entiers avec les blancs d'œufs, le sel et le poivre noir et versez-les sur la sauce.","Remuez délicatement à feu doux de temps en temps jusqu'à ce que les œufs soient pris comme vous l'aimez, puis saupoudrez de coriandre et servez chaud avec du pain complet."],
["Ce qui a changé : 1 cuillère à soupe d'huile d'olive pour toute la poêle, moins de sel, 2 des œufs remplacés par des blancs pour réduire le cholestérol, et plus de légumes.","Conseil pour les reins : les tomates et le concentré de tomate sont riches en potassium et le jaune d'œuf contient du phosphore ; vous pouvez réduire les tomates à 2 avec plus de poivrons, et utiliser plus de blancs d'œufs.","Conseil pour le diabète : la shakshouka est pauvre en glucides et riche en protéines ; les glucides viennent du pain, prenez donc une demi-galette de pain complet.","Convient à : personnes diabétiques, végétariens, régime sans gluten.","Références : Encyclopedia Cooking, Sayidaty, Layalina Yummy"]),
R(8908761,"Mufattah de chèvre (version maison)",
"Le mufattah est le plat de fête de la générosité en Arabie saoudite : un agneau ou une chèvre entier cuit et servi sur du riz. Voici une version maison réduite avec environ 600 g de chèvre maigre au lieu d'un animal entier, sans cubes de bouillon, avec peu de ghee et une salade sans pain frit.",
"4","1 assiette avec salade (environ 500 g)",
[["Pour la viande","600 g de gigot et d'épaule de chèvre avec l'os, gras visible retiré (poids de viande comestible)"],["Pour la viande","1 gros oignon, coupé en quartiers (150 g)"],["Pour la viande","1 tomate, coupée en quartiers (120 g)"],["Pour la viande","Épices entières : 2 citrons verts séchés, 1 bâton de cannelle, 5 gousses de cardamome, 4 clous de girofle, 2 feuilles de laurier ; plus 1 cuillère à café de bezar"],["Pour la viande","1,5 l d'eau"],["Pour la viande","Pour la dorure : 1 œuf (50 g) battu avec 3 cuillères à soupe de bouillon et une pincée de safran et de curcuma"],["Pour le riz","200 g de riz basmati, lavé et trempé 20 minutes"],["Pour le riz","1 petit oignon, finement haché (50 g)"],["Pour le riz","1 petite tomate, finement hachée (80 g)"],["Pour le riz","1 carotte, râpée (100 g)"],["Pour le riz","1 cuillère à soupe d'huile d'olive (13,5 g) et 2 cuillères à café de ghee (9 g)"],["Pour le riz","3/4 cuillère à café de sel (4 g), réparti entre la viande et le riz"],["Pour le riz","Environ 450 ml de bouillon de viande filtré"],["Pour la salade","2 concombres, hachés (200 g), 1 tomate (150 g)"],["Pour la salade","60 g de roquette et 60 g de laitue"],["Pour la salade","1 cuillère à soupe de jus de citron (15 g) et du sumac"]],
["Mettez la chèvre dans une marmite avec l'eau, portez à ébullition et écumez, puis ajoutez l'oignon, la tomate, les épices entières, le bezar et 1/4 cuillère à café du sel.","Laissez mijoter 1 1/2–2 heures jusqu'à ce qu'elle soit tendre (ou 45 minutes à l'autocuiseur).","Déposez la viande sur une plaque de four, filtrez le bouillon, laissez-le reposer et retirez la graisse à la surface.","Battez l'œuf avec 3 cuillères à soupe de bouillon, le safran et le curcuma, badigeonnez-en la viande et faites-la dorer sous la chaleur du haut du four à 220 °C pendant 15 minutes.","Dans une marmite, faites revenir l'oignon dans l'huile et le ghee, ajoutez la tomate et la carotte, puis le riz égoutté, le reste du sel et 450 ml du bouillon filtré.","Quand ça bout, couvrez et laissez mijoter 15–20 minutes jusqu'à ce que ce soit cuit. Vous pouvez fumer le riz et la viande avec un morceau de charbon de bois incandescent dans un bol en métal pendant 3 minutes.","Mélangez les ingrédients de la salade avec le jus de citron et le sumac, sans sel ni pain frit.","Étalez le riz sur un grand plat, posez la viande dessus et servez avec la salade."],
["Ce qui a changé : une version maison avec environ 600 g de viande au lieu d'une chèvre entière, pas de cubes de bouillon, graisse retirée du bouillon, peu de ghee, une salade sans pain frit et pas de foie frit ni d'abats.","Conseil pour les reins : avec sa salade, cette assiette est riche en potassium (viande, tomate, carotte, légumes à feuilles) ; utilisez moins de tomate et de roquette et limitez-vous à 90–100 g de viande cuite.","Conseil pour le diabète : une assiette contient environ 54 g de glucides ; commencez par la salade et évitez le dessert après le repas.","Convient à : personnes diabétiques, régime sans gluten.","Références : Encyclopedia Cooking (encyclopediacooking.com), Saudipedia (Kabsa et Mufattah), Sayidaty Kitchen"]),
R(8924859,"Tawa du Qassim",
"Le tawa (aussi appelé taawa ou manafeekh) est un petit-déjeuner d'hiver traditionnel du Qassim et du Najd : de petites galettes de pâte complète levée aux graines de nigelle qui gonflent à la cuisson, servies avec du miel ou du sirop de dattes et du thé ou du lait. Ici, les galettes sont cuites dans un four chaud ou une poêle antiadhésive au lieu d'être frites, avec du laban allégé, moitié moins de sucre et une quantité mesurée de miel.",
"8","2 petites galettes au miel (environ 75 g)",
[["Pour la pâte","200 g de farine complète"],["Pour la pâte","100 g de farine blanche"],["Pour la pâte","1 cuillère à soupe de sucre (15 g)"],["Pour la pâte","2 cuillères à café de levure instantanée (6 g)"],["Pour la pâte","2 cuillères à café de graines de nigelle (cumin noir)"],["Pour la pâte","⅓ cuillère à café de sel (2 g)"],["Pour la pâte","1 œuf (50 g)"],["Pour la pâte","2 cuillères à café d'huile d'olive (10 ml)"],["Pour la pâte","200 ml de laban allégé tiède"],["Pour badigeonner et servir","2 cuillères à café d'huile d'olive (10 ml)"],["Pour badigeonner et servir","3 cuillères à soupe de miel (60 g)"]],
["Mélangez les deux farines avec le sucre, la levure, les graines de nigelle et le sel.","Ajoutez l'œuf, l'huile et le laban tiède et pétrissez jusqu'à obtenir une pâte souple et lisse, en ajoutant une cuillère d'eau si nécessaire ; couvrez et laissez lever 1 heure.","Chauffez le four à 240 °C avec une plaque en fonte ou une pierre à pain à l'intérieur.","Divisez la pâte en 16 petites boules et aplatissez chacune à la main en une galette fine d'environ 10 cm de large.","Badigeonnez légèrement les galettes d'huile et faites-les cuire sur la plaque chaude 5–6 minutes, en les retournant à mi-cuisson, jusqu'à ce qu'elles soient gonflées et dorées. (Vous pouvez aussi les cuire dans une poêle antiadhésive couverte à feu moyen, 2 minutes de chaque côté.)","Empilez les galettes sur une assiette, versez le miel dessus et servez chaud."],
["Ce qui a changé : cuites au four ou à la poêle au lieu d'être frites, deux tiers de farine complète, laban allégé, moitié moins de sucre habituel dans la pâte, et miel limité (environ 2 cuillères à café par portion).","Conseil pour les reins : la farine complète et le laban contiennent du phosphore et du potassium ; vous pouvez utiliser plus de farine blanche et vous limiter à 2 galettes.","Conseil pour le diabète : une portion (2 galettes) contient environ 37 g de glucides ; supprimez le miel et servez avec un œuf dur ou du labneh allégé et du concombre.","Convient à : santé cardiaque et tension artérielle, maladie rénale (sans dialyse), personnes sous dialyse, végétariens.","Références : Encyclopedia Cooking, Wikipédia en arabe (cuisine saoudienne : tawa), Cookpad Arabie saoudite"]),
]
